} Point;

int cmp_point(const void *a, const void *b) {
    Point *x = (Point *)a;
    Point *y = (Point *)b;
    if (x->r != y->r) return x->r - y->r;
    return x->c - y->c;
}

ll modpow(ll a, ll e) {
    ll r = 1;
    while (e > 0) {
        if (e & 1) r = (r * a) % MOD;
        a = (a * a) % MOD;
        e >>= 1;
    }
    return r;
}

ll comb(int n, int k, ll *fact, ll *invfact) {
    if (k < 0 || k > n) return 0;
    return (((fact[n] * invfact[k]) % MOD) * invfact[n - k]) % MOD;
}

